from pysat.solvers import Glucose3
from pysat.card import CardEnc, EncType

# 14 vertices
n = 14

# Variables: x_{i,j} for i < j
# Map (i,j) to 1..91
def var(i, j):
    if i > j:
        i, j = j, i
    # i from 0 to 12, j from i+1 to 13
    # index = i * 13 - i*(i-1)//2 + j - i - 1 + 1
    # Let's just use a dictionary
    return var_map[(i, j)]

var_map = {}
idx = 1
for i in range(n):
    for j in range(i+1, n):
        var_map[(i, j)] = idx
        idx += 1

solver = Glucose3()

# Fixed edges
fixed_edges = [(1,11), (0,13), (7,9), (1,13), (4,11), (6,9)]
for u, v in fixed_edges:
    if u > v:
        u, v = v, u
    solver.add_clause([var(u, v)])

# Degree constraints
for i in range(n):
    neighbors = []
    for j in range(n):
        if i != j:
            neighbors.append(var(i, j))

    # degree >= 4
    # which means sum >= 4
    cnf_ge = CardEnc.atleast(lits=neighbors, bound=4, encoding=EncType.seqcounter, vpool=None)
    for clause in cnf_ge.clauses:
        solver.add_clause(clause)

    # degree <= 5
    # which means sum <= 5
    cnf_le = CardEnc.atmost(lits=neighbors, bound=5, encoding=EncType.seqcounter, vpool=None)
    for clause in cnf_le.clauses:
        solver.add_clause(clause)

if solver.solve():
    model = solver.get_model()
    edges = []
    for i in range(n):
        for j in range(i+1, n):
            if model[var(i, j) - 1] > 0:
                edges.append((i, j))
    print("SAT")
    print(edges)
else:
    print("UNSAT")

from pysat.solvers import Glucose3
from pysat.card import CardEnc, EncType
from pysat.formula import IDPool

n = 14
vpool = IDPool()

def var(i, j):
    if i > j:
        i, j = j, i
    return vpool.id(f"edge_{i}_{j}")

solver = Glucose3()

fixed_edges = [(1,11), (0,13), (7,9), (1,13), (4,11), (6,9)]
for u, v in fixed_edges:
    solver.add_clause([var(u, v)])

for i in range(n):
    neighbors = []
    for j in range(n):
        if i != j:
            neighbors.append(var(i, j))

    cnf_ge = CardEnc.atleast(lits=neighbors, bound=4, encoding=EncType.seqcounter, vpool=vpool)
    for clause in cnf_ge.clauses:
        solver.add_clause(clause)

    cnf_le = CardEnc.atmost(lits=neighbors, bound=5, encoding=EncType.seqcounter, vpool=vpool)
    for clause in cnf_le.clauses:
        solver.add_clause(clause)

if solver.solve():
    model = solver.get_model()
    edges = []
    for i in range(n):
        for j in range(i+1, n):
            if model[var(i, j) - 1] > 0:
                edges.append((i, j))
    print("SAT")
    print(edges)
else:
    print("UNSAT")
